def compute(vars):
    parent_value = vars["Net Asset Value at Period End"]
    x0 = vars["Total Assets"]
    total_liabilities = -parent_value + x0
    return {
        "value": total_liabilities,
        "trace": {
            "Net Asset Value at Period End": parent_value,
            "Total Assets": x0,
            "output_meta": {
                "currency": "$",
                "scale": "millions",
                "unit": None
            }
        }
    }
